            "statusMessage": "Loading pm init, pm where and pm show",
            "type": "command",
            "timeout": 30
          },
          {
            "command": "pm prime --request-rule --hook-json",
            "statusMessage": "Loading the rule for asking the owner",
            "type": "command",
            "timeout": 10
          }
        ],
        "matcher": "startup|resume|clear|compact"
      }
    ],
    "SubagentStart": [
      {
        "hooks": [
          {
            "command": "pm prime --rules 1 --hook-json",
            "statusMessage": "Loading pm rules (1 of 3)",
            "type": "command",
            "timeout": 15
          },
          {
            "command": "pm prime --rules 2 --hook-json",
            "statusMessage": "Loading pm rules (2 of 3)",
            "type": "command",
            "timeout": 15
          },
          {
            "command": "pm prime --rules 3 --hook-json",
            "statusMessage": "Loading pm rules (3 of 3)",
            "type": "command",
            "timeout": 15
          },
          {
            "command": "pm prime --subagent --hook-json",
            "statusMessage": "Loading pm's git rule for agents",
            "type": "command",
            "timeout": 15
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "command": "pm hook ask --runtime codex || exit 1",
            "statusMessage": "Closing the questions this prompt answers",
            "type": "command",
            "timeout": 10
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "hooks": [
          {
            "command": "pm hook ask --runtime codex || exit 1",
            "statusMessage": "Raising the question for the site",
            "type": "command",
            "timeout": 30
          }
        ],
        "matcher": "request_user_input_async"
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "command": "pm hook owner-request --runtime codex || exit 1",
            "statusMessage": "Checking for owner requests asked only in chat",
            "type": "command",
            "timeout": 45
          },
          {
            "command": "pm hook stop || exit 1",
            "statusMessage": "Checking for uncommitted records",
            "type": "command",
            "timeout": 10
          }
        ]
      }
    ],
    "SubagentStop": [
      {
        "hooks": [
          {
            "command": "pm hook stop || exit 1",
            "statusMessage": "Checking for uncommitted records",
            "type": "command",
            "timeout": 10
          }
        ]
      }
    ],
    "SessionEnd": [
      {
        "hooks": [
          {
            "command": "pm hook session-end || exit 1",
            "statusMessage": "Clearing this session's interactive mode",
            "type": "command",
            "timeout": 10
          }
        ]
      }
    ]
  }
}
